const SPLASH_PEN = [["M180,88 L372,88 L470,195", 70, 2.05, 0.16], ["M248,170 L412,170", 55, 2.17, 0.12], ["M310,248 L432,248 L382,318", 60, 2.29, 0.12], ["M578,68 L322,410", 44, 2.41, 0.12], ["M828,102 C770,55 640,60 600,130 C560,200 640,240 720,280 C800,320 850,380 760,410 C690,435 600,410 575,358", 118, 2.53, 0.22], ["M100,600 L335,600", 240, 2.78, 0.16], ["M330,600 L545,600", 240, 2.86, 0.16], ["M540,600 L765,600", 240, 2.94, 0.16], ["M760,600 L985,600", 240, 3.02, 0.16], ["M225,765 L865,765", 80, 3.1, 0.16]];
const handReduced = () => matchMedia('(prefers-reduced-motion: reduce)').matches;
let handSeq = 0;
/* 回傳一段手寫字 SVG（由左而右一字一字寫出）；沒有的字跳過 */
function handSVG(text, o = {}){
  const size = o.size || 40, k = size / 1024, gap = o.gap ?? .12, start = o.start ?? 0, dur = o.dur ?? .2, color = o.color || '#00223D';
  const chars = [...text].filter(c => HAND[c]), total = chars.reduce((s, c) => s + HAND[c][0] * k, 0);
  const W = Math.max(total + 8, o.w || 0), H = size * 1.35, base = size * 1.02; let x = (W - total) / 2;
  const id = 'hd' + (++handSeq); let defs = '', body = '';
  chars.forEach((c, i) => { const [adv, d] = HAND[c], w = adv * k;
    defs += `<clipPath id="${id}c${i}"><rect class="hd-wipe" style="animation-delay:${(start + i * gap).toFixed(2)}s;animation-duration:${dur}s" x="${(x - 2).toFixed(1)}" y="0" width="${(w + 4).toFixed(1)}" height="${H.toFixed(1)}"/></clipPath>`;
    body += `<g clip-path="url(#${id}c${i})"><path transform="translate(${x.toFixed(1)},${base.toFixed(1)}) scale(${k.toFixed(5)},${(-k).toFixed(5)})" d="${d}" fill="${color}" stroke="${color}" stroke-width="22" stroke-linejoin="round"/></g>`;
    x += w; });
  const ul = o.underline ? `<path class="hd-ul" pathLength="1" style="animation-delay:${(start + chars.length * gap + .05).toFixed(2)}s" d="M6,${(H - 4).toFixed(1)} Q${(W / 2).toFixed(1)},${(H - 12).toFixed(1)} ${(W - 6).toFixed(1)},${(H - 5).toFixed(1)}" filter="url(#hd-rough)"/>` : '';
  return `<svg class="hand${o.cls ? ' ' + o.cls : ''}" viewBox="0 0 ${W.toFixed(1)} ${H.toFixed(1)}" width="${W.toFixed(0)}" height="${H.toFixed(0)}" aria-label="${text}" role="img"><defs>${defs}<filter id="hd-rough"><feTurbulence type="fractalNoise" baseFrequency=".9" numOctaves="1" seed="3"/><feDisplacementMap in="SourceGraphic" scale="3"/></filter></defs>${body}${ul}</svg>`;
}
const handEnd = (text, o = {}) => (o.start ?? 0) + [...text].filter(c => HAND[c]).length * (o.gap ?? .12) + (o.dur ?? .2);
function mapSVG(cls, lit = [], seq = false){
  return `<svg class="${cls}" viewBox="40 60 720 680" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><g>${GEO.filter(x => HOME[x.c]).map(x => { const i = lit.indexOf(x.c);
    return `<path d="${x.d}"${i >= 0 ? ` class="lit" style="animation-delay:${seq ? (.6 + i * .35).toFixed(2) : .6}s"` : ''}/>`; }).join('')}</g></svg>`;
}

/* 開場畫面（約 3.6 秒）：地圖淡入 → 標語 → 橘色底線 → 永信 Logo 沿筆順寫出 → 淡出。每支手機只播第一次 */
function showSplash(force){
  let seen = false; try { seen = localStorage.getItem('ys_splash_v1') === '1'; } catch(e) {}
  if (seen && !force) return;
  const reduced = handReduced(), k = 37.9 / 1024, base = 470;
  const pen = SPLASH_PEN.map(([d, w, t, dur]) => `<path d="${d}" stroke-width="${w}" pathLength="1" class="sp-pen" style="animation-delay:${t}s;animation-duration:${dur}s"/>`).join('');
  let x = 35, clips = '', gl = '';
  [...'一分鐘找到自己的歐洲'].forEach((c, i) => { const [adv, d] = HAND[c], w = adv * k;
    clips += `<clipPath id="spc${i}"><rect class="sp-wipe" style="animation-delay:${(0.4 + i * .12).toFixed(2)}s" x="${(x - 2).toFixed(1)}" y="${base - 45}" width="${(w + 4).toFixed(1)}" height="70"/></clipPath>`;
    gl += `<g clip-path="url(#spc${i})"><path class="sp-gly" transform="translate(${x.toFixed(1)},${base}) scale(${k},${-k})" d="${d}"/></g>`; x += w; });
  const el = document.createElement('div');
  el.className = 'splash' + (reduced ? ' still' : ''); el.setAttribute('role', 'img'); el.setAttribute('aria-label', '一分鐘找到自己的歐洲・永信旅遊');
  el.innerHTML = `${mapSVG('sp-map')}
    <svg class="sp-fg" viewBox="0 0 390 844" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><defs>
      <mask id="sp-m" maskUnits="userSpaceOnUse" x="0" y="0" width="1080" height="825">${pen}</mask>
      <filter id="sp-rough"><feTurbulence type="fractalNoise" baseFrequency=".9" numOctaves="1" seed="3"/><feDisplacementMap in="SourceGraphic" scale="3.5"/></filter>${clips}</defs>
      <g transform="translate(85,205) scale(.2037)"><image href="img/ys-logo.png" width="1080" height="825" mask="url(#sp-m)"/></g>${gl}
      <path class="sp-ul" pathLength="1" filter="url(#sp-rough)" d="M42,500 Q200,489 352,499"/></svg>
    <p class="sp-skip">點一下跳過</p>`;
  document.body.append(el);
  let done = false;
  const close = () => { if (done) return; done = true; try { localStorage.setItem('ys_splash_v1', '1'); } catch(e) {}
    el.classList.add('out'); setTimeout(() => el.remove(), 320); };
  el.addEventListener('click', close);
  setTimeout(close, reduced ? 600 : 3300);
}

/* 重要時刻：生日、準備出發、歡迎回來。hand＝手寫主句，sub＝一般字說明，lit＝地圖要點亮的國家，seq＝依序點亮 */
function showMoment({ hand, sub = '', extra = '', lit = [], seq = false, hold = 1.6, onClose }){
  const reduced = handReduced(), end = handEnd(hand, { start:.5, gap:.16, dur:.24 });
  const el = document.createElement('div');
  el.className = 'moment' + (reduced ? ' still' : ''); el.setAttribute('role', 'dialog'); el.setAttribute('aria-label', hand);
  el.innerHTML = `${mapSVG('mo-map', lit, seq)}
    <div class="mo-body">${handSVG(hand, { size:58, start:.5, gap:.16, dur:.24, underline:true, color:'#00223D' })}
      <p class="mo-sub" style="animation-delay:${(end + .3).toFixed(2)}s">${sub}</p>${extra ? `<div class="mo-extra" style="animation-delay:${(end + .5).toFixed(2)}s">${extra}</div>` : ''}</div>
    <p class="sp-skip">點一下關閉</p>`;
  document.body.append(el);
  // 有要點亮的國家時，地圖鏡頭對準那一區
  const lp = [...el.querySelectorAll('.mo-map path.lit')];
  if (lp.length) { const bb = lp.map(p => p.getBBox()).reduce((a, b) => ({ x:Math.min(a.x,b.x), y:Math.min(a.y,b.y), x2:Math.max(a.x2,b.x+b.width), y2:Math.max(a.y2,b.y+b.height) }), { x:1e9, y:1e9, x2:-1e9, y2:-1e9 });
    const w = Math.max(320, (bb.x2 - bb.x) * 3.2), h = w * 680 / 720, cx = (bb.x + bb.x2) / 2, cy = (bb.y + bb.y2) / 2 + h * .12;
    el.querySelector('.mo-map').setAttribute('viewBox', `${cx - w / 2} ${cy - h / 2} ${w} ${h}`); }
  let done = false;
  const close = () => { if (done) return; done = true; el.classList.add('out'); setTimeout(() => { el.remove(); if (onClose) onClose(); }, 320); };
  el.addEventListener('click', close);
  setTimeout(close, reduced ? 2500 : (Math.max(end + 1, lit.length && seq ? .6 + lit.length * .35 + .4 : 0) + hold) * 1000);
  return close;
}

/* 載入中：橘色麥克筆底線來回畫，取代轉圈圈 */
const loaderHTML = (text = '載入中') => `<div class="hd-loader" role="status"><svg viewBox="0 0 120 16" aria-hidden="true"><path pathLength="1" d="M6,10 Q60,2 114,9"/></svg><span>${text}…</span></div>`;

/* 分享用動態角色卡：在畫布上畫 3 秒動畫並錄成影片（iPhone 錄成 MP4、Android 錄成 WebM），不支援時改存圖片 */
async function makeRoleClip({ roleShort, roleName, alias, avatarSVG, onProgress }){
  const W = 720, Hh = 1280, cv = document.createElement('canvas'); cv.width = W; cv.height = Hh;
  const g = cv.getContext('2d');
  const img = await new Promise(res => { const im = new Image(); im.onload = () => res(im); im.onerror = () => res(null); im.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(avatarSVG); });
  const map = GEO.filter(x => HOME[x.c]).map(x => new Path2D(x.d));
  const text = [...('我是' + roleShort)].filter(c => HAND[c]), size = 96, k = size / 1024;
  const total = text.reduce((s, c) => s + HAND[c][0] * k, 0), x0 = (W - total) / 2, base = 820;
  const glyphs = text.map(c => ({ p:new Path2D(HAND[c][1]), w:HAND[c][0] * k }));
  const tag = [...'一分鐘找到自己的歐洲'].map(c => ({ p:new Path2D(HAND[c][1]), w:HAND[c][0] * 30 / 1024 }));
  const ease = t => 1 - Math.pow(1 - Math.min(1, Math.max(0, t)), 3);
  const draw = t => {
    g.fillStyle = '#F9F6EF'; g.fillRect(0, 0, W, Hh);
    // 淡淡的歐洲地圖
    g.save(); const sc = Hh / 680 * (1 + .03 * t / 3); g.translate(W / 2, Hh / 2); g.scale(sc, sc); g.translate(-400, -400);
    g.globalAlpha = Math.min(1, t / .5) * .9; g.fillStyle = 'rgba(0,34,61,.07)'; g.strokeStyle = 'rgba(0,34,61,.16)'; g.lineWidth = 1 / sc;
    map.forEach(p => { g.fill(p); g.stroke(p); }); g.restore();
    // 角色頭像彈出
    const a = ease((t - .1) / .4); if (img && a > 0) { const s = 360 * (.7 + .3 * a); g.globalAlpha = a; g.drawImage(img, (W - s) / 2, 300 - s / 2 + 40, s, s); g.globalAlpha = 1; }
    // 手寫「我是○○」一字一字寫出
    let x = x0; glyphs.forEach((gl, i) => { const p = ease((t - .5 - i * .2) / .22); if (p > 0) { g.save(); g.beginPath(); g.rect(x - 4, base - size, (gl.w + 8) * p, size * 1.4); g.clip();
      g.translate(x, base); g.scale(k, -k); g.fillStyle = '#00223D'; g.strokeStyle = '#00223D'; g.lineWidth = 26; g.lineJoin = 'round'; g.fill(gl.p); g.stroke(gl.p); g.restore(); } x += gl.w; });
    // 橘色麥克筆底線
    const u = ease((t - .5 - glyphs.length * .2 - .05) / .3); if (u > 0) { g.save(); g.strokeStyle = '#F39500'; g.lineWidth = 14; g.lineCap = 'round';
      g.beginPath(); const xa = x0 - 10, xb = x0 + total + 10; g.moveTo(xa, base + 34); g.quadraticCurveTo((xa + xb) / 2, base + 22, xa + (xb - xa) * u, base + 32 - 2 * u); g.stroke(); g.restore(); }
    // 角色名與說明
    const n = ease((t - 1.9) / .4); if (n > 0) { g.globalAlpha = n; g.textAlign = 'center'; g.fillStyle = '#B85C00'; g.font = '700 44px "Noto Sans TC","PingFang TC",sans-serif'; g.fillText(roleName, W / 2, 940);
      g.fillStyle = '#6B6457'; g.font = '500 30px "Noto Sans TC","PingFang TC",sans-serif'; g.fillText(alias, W / 2, 990); g.globalAlpha = 1; }
    // 底部：標語與網址
    g.globalAlpha = Math.min(1, t / .6); let tx = (W - tag.reduce((s, c) => s + c.w, 0)) / 2;
    tag.forEach(c => { g.save(); g.translate(tx, 1150); g.scale(30 / 1024, -30 / 1024); g.fillStyle = '#00223D'; g.fill(c.p); g.restore(); tx += c.w; });
    g.textAlign = 'center'; g.fillStyle = '#9A9184'; g.font = '500 24px "Noto Sans TC",sans-serif'; g.fillText('ky0126.github.io/FJUIEC/find-my-europe', W / 2, 1200); g.globalAlpha = 1;
  };
  const DUR = 3.2;
  if (!window.MediaRecorder || !cv.captureStream) { draw(DUR); return new Promise(res => cv.toBlob(b => res({ blob:b, ext:'png', type:'image/png' }), 'image/png')); }
  const type = ['video/mp4;codecs=avc1', 'video/mp4', 'video/webm;codecs=vp9', 'video/webm'].find(m => MediaRecorder.isTypeSupported(m)) || '';
  const rec = new MediaRecorder(cv.captureStream(30), type ? { mimeType:type, videoBitsPerSecond:2500000 } : undefined), chunks = [];
  rec.ondataavailable = e => e.data.size && chunks.push(e.data);
  const done = new Promise(res => rec.onstop = res);
  draw(0); rec.start();
  const t0 = performance.now();
  await new Promise(res => { const step = () => { const t = (performance.now() - t0) / 1000; draw(Math.min(t, DUR)); if (onProgress) onProgress(Math.min(1, t / DUR)); t < DUR ? requestAnimationFrame(step) : res(); }; requestAnimationFrame(step); });
  rec.stop(); await done;
  const mt = rec.mimeType || type || 'video/webm', ext = /mp4/.test(mt) ? 'mp4' : 'webm';
  return { blob:new Blob(chunks, { type:mt.split(';')[0] }), ext, type:mt.split(';')[0] };
}
